// swift-tools-version: 6.0
import PackageDescription

// Shared macOS sources are mirrored into .generated by
// scripts/linux/sync-shared-sources.py (see linux/shared-sources.json).
let generated = ".generated"

// terminal-integration: SwiftPM drops pkg-config's -Wl,-rpath, so binaries
// find libghostty through an absolute rpath to the dev build and an
// $ORIGIN-relative one for an installed layout (<prefix>/bin + <prefix>/lib).
let ghosttyLinkerSettings: [LinkerSetting] = [
    .unsafeFlags([
        "-Xlinker", "-rpath", "-Xlinker", "\(Context.packageDirectory)/.deps/ghostty/lib",
        "-Xlinker", "-rpath", "-Xlinker", "$ORIGIN/../lib",
    ]),
]

let package = Package(
    name: "ToasttyLinux",
    products: [
        .executable(name: "toastty", targets: ["toastty"]),
        .executable(name: "toastty-agent-shim", targets: ["toastty-agent-shim"]),
        // gtk-shell: the GTK4 + libadwaita frontend.
        .executable(name: "toastty-linux", targets: ["ToasttyLinux"]),
        // app-logic: the UI-free Sources/App layer (AppStore, automation socket, agents, remote access).
        .library(name: "ToasttyAppLogic", targets: ["ToasttyAppLogic"]),
    ],
    dependencies: [
        .package(url: "https://github.com/apple/swift-crypto.git", from: "3.0.0"),
        .package(url: "https://github.com/OpenCombine/OpenCombine.git", from: "0.14.0"),
        .package(url: "https://github.com/swiftlang/swift-markdown.git", from: "0.5.0"),
    ],
    targets: [
        // MARK: shared-core (owned by the shared-core workstream)
        // Linux stand-ins for Foundation APIs that swift-corelibs-foundation
        // lacks; implicitly imported into every mirrored shared target.
        .target(
            name: "ToasttyFoundationShim",
            dependencies: [.product(name: "Markdown", package: "swift-markdown")],
            path: "Sources/Shims/ToasttyFoundationShim"
        ),
        .target(name: "RemoteProtocol", dependencies: ["ToasttyFoundationShim"], path: "\(generated)/RemoteProtocol"),
        .target(
            name: "CoreState",
            dependencies: [
                "ToasttyFoundationShim",
                "RemoteProtocol",
                .product(name: "Crypto", package: "swift-crypto"),
            ],
            path: "\(generated)/CoreState"
        ),
        .target(name: "CodexReconciliation", dependencies: ["ToasttyFoundationShim"], path: "\(generated)/CodexReconciliation"),
        .target(
            name: "ToasttyCLIKit",
            dependencies: ["ToasttyFoundationShim", "CoreState", "RemoteProtocol"],
            path: "\(generated)/ToasttyCLIKit"
        ),
        .executableTarget(name: "toastty", dependencies: ["ToasttyFoundationShim", "ToasttyCLIKit"], path: "\(generated)/toastty"),
        .executableTarget(
            name: "toastty-agent-shim",
            dependencies: ["ToasttyFoundationShim", "CoreState", "RemoteProtocol"],
            path: "\(generated)/toastty-agent-shim"
        ),
        .testTarget(
            name: "CoreStateTests",
            dependencies: ["ToasttyFoundationShim", "CoreState", "RemoteProtocol"],
            path: "\(generated)/CoreStateTests"
        ),
        .testTarget(
            name: "ToasttyCLITests",
            dependencies: ["ToasttyFoundationShim", "ToasttyCLIKit", "RemoteProtocol"],
            path: "\(generated)/ToasttyCLITests"
        ),
        .testTarget(
            name: "CodexReconciliationTests",
            dependencies: ["ToasttyFoundationShim", "CodexReconciliation"],
            path: "\(generated)/CodexReconciliationTests"
        ),
        // MARK: end shared-core

        // MARK: gtk-shell (owned by the gtk-shell workstream)
        .systemLibrary(name: "CGtk", path: "Sources/CGtk", pkgConfig: "gtk4 libadwaita-1"),
        .target(name: "CGtkShim", dependencies: ["CGtk"], path: "Sources/CGtkShim"),
        .target(
            name: "ToasttyLinuxUI",
            dependencies: ["CGtk", "CGtkShim", "CWebKitGtk", "CWebKitShim", "CoreState", "RemoteProtocol", "GhosttyKit", "ToasttyAppLogic"],
            path: "Sources/ToasttyLinux/UI",
            swiftSettings: [.define("TOASTTY_LINUX_APP_LOGIC")],
            linkerSettings: ghosttyLinkerSettings
        ),
        .executableTarget(
            name: "ToasttyLinux",
            dependencies: ["ToasttyLinuxUI"],
            path: "Sources/ToasttyLinux/Executable"
        ),
        .testTarget(
            name: "ToasttyLinuxTests",
            dependencies: ["ToasttyLinuxUI", "CoreState"],
            path: "Tests/ToasttyLinuxTests"
        ),
        // MARK: panels-remote (owned by the panels-remote workstream)
        // WebKitGTK 6.0 for the right panel (browser, local documents,
        // Scratchpad); the panel UI lives in Sources/ToasttyLinux/UI/RightPanel.
        .systemLibrary(name: "CWebKitGtk", path: "Sources/CWebKitGtk", pkgConfig: "webkitgtk-6.0"),
        .target(name: "CWebKitShim", dependencies: ["CWebKitGtk"], path: "Sources/CWebKitShim"),
        .testTarget(
            name: "ToasttyLinuxPanelsTests",
            dependencies: ["ToasttyLinuxUI", "CoreState"],
            path: "Tests/ToasttyLinuxPanelsTests"
        ),
        // MARK: end panels-remote

        // MARK: terminal-integration (owned by the terminal-integration workstream)
        // libghostty + the Toastty GTK4 widget (linux/ghostty). Build first:
        // linux/ghostty/build-libghostty.sh (linux/env.sh puts its pkg-config
        // file on PKG_CONFIG_PATH). The terminal host itself lives in
        // Sources/ToasttyLinux/UI/Terminal inside ToasttyLinuxUI.
        .systemLibrary(name: "GhosttyKit", path: "ghostty/GhosttyKit", pkgConfig: "toastty-ghostty"),
        // MARK: end terminal-integration

        // MARK: app-logic (owned by the app-logic workstream)
        // AppKit/UserNotifications/CoreImage stand-ins for the UI-free App
        // layer; UI-ish calls route through LinuxPlatformServices.
        .target(
            name: "ToasttyAppKitShim",
            dependencies: [
                "ToasttyFoundationShim",
                .product(name: "Markdown", package: "swift-markdown"),
                .product(name: "OpenCombine", package: "OpenCombine"),
                .product(name: "OpenCombineFoundation", package: "OpenCombine"),
                .product(name: "OpenCombineDispatch", package: "OpenCombine"),
            ],
            path: "Sources/Shims/ToasttyAppKitShim"
        ),
        // NWListener/NWConnection subset over POSIX sockets.
        .target(
            name: "ToasttyNetworkShim",
            dependencies: ["ToasttyFoundationShim"],
            path: "Sources/Shims/ToasttyNetworkShim"
        ),
        .target(
            name: "ToasttyAppLogic",
            dependencies: [
                "ToasttyFoundationShim",
                "ToasttyAppKitShim",
                "ToasttyNetworkShim",
                "CoreState",
                "RemoteProtocol",
                "CodexReconciliation",
                .product(name: "Crypto", package: "swift-crypto"),
                .product(name: "OpenCombine", package: "OpenCombine"),
                .product(name: "OpenCombineFoundation", package: "OpenCombine"),
                .product(name: "OpenCombineDispatch", package: "OpenCombine"),
            ],
            path: "\(generated)/ToasttyAppLogic"
        ),
        .testTarget(
            name: "ToasttyAppLogicTests",
            dependencies: [
                "ToasttyFoundationShim",
                "ToasttyAppKitShim",
                "ToasttyNetworkShim",
                "ToasttyAppLogic",
                "CoreState",
                "RemoteProtocol",
                "CodexReconciliation",
                .product(name: "Crypto", package: "swift-crypto"),
                .product(name: "OpenCombine", package: "OpenCombine"),
                .product(name: "OpenCombineFoundation", package: "OpenCombine"),
                .product(name: "OpenCombineDispatch", package: "OpenCombine"),
            ],
            path: "\(generated)/ToasttyAppLogicTests"
        ),
        // MARK: end app-logic
    ]
)
